// test_ebpf.cpp
// eBPF 功能专项测试
// 测试 BPF 程序加载、kprobe 挂载、流量数据采集
// 编译: g++ -std=c++17 -O2 -Wall -Iinclude -o test/test_ebpf test/test_ebpf.cpp src/net_traffic.cpp src/traffic_analyzer.cpp src/serializer.cpp src/net_info.cpp src/logger.cpp $(pkg-config --cflags --libs libbpf) -lglog -lbpf

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <chrono>
#include <thread>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/stat.h>
#include <sstream>
#include <iomanip>
#include <cstring>

#include "net_traffic.h"
#include "logger.hpp"

using namespace weaknet_dbus;

// 测试结果统计
struct TestStats {
    int total = 0;
    int passed = 0;
    int failed = 0;

    void addResult(bool success, const std::string& testName) {
        total++;
        if (success) {
            passed++;
            std::cout << "  ✅ " << testName << std::endl;
        } else {
            failed++;
            std::cout << "  ❌ " << testName << std::endl;
        }
    }

    void print() {
        std::cout << "\n📊 测试统计: 总计=" << total 
                  << ", 通过=" << passed 
                  << ", 失败=" << failed 
                  << ", 成功率=" << (total > 0 ? (passed * 100.0 / total) : 0.0) << "%" << std::endl;
    }
};

TestStats g_stats;

// 探测并解析有效的 BPF 对象文件路径
static std::string resolveBpfObjectPath(const std::string& bpfName = "flow_rate.bpf.o") {
    const std::vector<std::string> candidatePaths = {
        "server/build/" + bpfName,
        "build/" + bpfName,
        "/home/radxa/weaknet/server/build/" + bpfName,
